from hdr import *
r.append(R(7512154,"मिनी फ़ाइलो कद्दू पाई",
"मसालेदार कद्दू को फ़ाइलो की टोकरियों में भरा जाता है और ऊपर कद्दू के बीज और संतरे का छिलका डाला जाता है।",
"12","57 ग्राम",
["8 शीट फ़ाइलो पेस्ट्री (24x8 सेमी के चौकोर टुकड़ों में, प्रत्येक 40 ग्राम)","6 बार तेल का स्प्रे","200 ग्राम कद्दू या बटरनट स्क्वैश, छिला हुआ और छोटे टुकड़ों में कटा हुआ","2 छोटे चम्मच दानेदार स्वीटनर (वैकल्पिक)","2 अंडे, फेंटे हुए","1/2 छोटा चम्मच जायफल","1/2 छोटा चम्मच दालचीनी","1/2 छोटा चम्मच पिसी अदरक","एक चुटकी पिसी लौंग","2 बड़े चम्मच 0% वसा वाला ग्रीक दही","10 ग्राम कद्दू के बीज","1 संतरे का छिलका"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। एक छिछली मफ़िन ट्रे को हल्का चिकना करें।","फ़ाइलो पेस्ट्री को 8 सेमी के चौकोर टुकड़ों में काटें और एक तरफ़ थोड़ा तेल स्प्रे करें। हर मफ़िन खाने में एक फ़ाइलो चौकोर टुकड़ा लगाएँ। और टुकड़ों पर तेल स्प्रे करें और उन्हें ऊपर रखें। इसे दोहराएँ ताकि हर मफ़िन खाने में पेस्ट्री की तीन परतें हों।","इसी बीच, एक बड़े कटोरे में अंडे, कद्दू, दही और मसाले मिलाकर भरावन तैयार करें।","भरावन को पेस्ट्री केसों में डालें और 10-12 मिनट बेक करें, जब तक फ़ाइलो केस हल्का भूरा न हो जाए और कद्दू बीच में अब भी थोड़ा हिलता हुआ महसूस हो। परोसने के लिए ऊपर कद्दू के बीज और संतरे का छिलका डालें।"],
["यदि आप चाहें, तो एक बड़ी पाई बना सकते हैं - बेकिंग टिन में फ़ाइलो पेस्ट्री बिछाएँ और पकाने के लिए 8-10 मिनट अतिरिक्त दें।",fv(0)]))
r.append(R(7516891,"ओरिएंटल बीफ़ स्टर-फ्राई",
"तैयार करने में तेज़ और आसान, स्वाद और स्वादिष्ट सब्ज़ियों से भरपूर, यह रेसिपी तब एकदम सही है जब आपको तुरंत सेहतमंद भोजन चाहिए।",
"4","323 ग्राम",
["2 छोटे चम्मच वनस्पति तेल","400 ग्राम दुबला बीफ़ स्टेक (रंप या सिरलॉइन)","4 फांक लहसुन, कुचला हुआ","2 पीली या लाल शिमला मिर्च, बीज निकालकर कटी हुई","200 ग्राम ब्रोकली, छोटे फूलों में कटी हुई","4 हरे प्याज़, कटे हुए","2 पाक चोई (बोक चोय), कटी हुई","1 छोटा डिब्बा (200 ग्राम) वॉटर चेस्टनट, छाने और कटे हुए","2 बड़े चम्मच ऑयस्टर सॉस"],
["नॉन-स्टिक फ्राइंग पैन या कड़ाही में तेल गरम करें। स्टेक से चर्बी हटाएँ, पतली पट्टियों में काटें और पैन में डालें।","1–2 मिनट तेज़ आँच पर चलाते हुए भूनें ताकि बाहर से सील हो जाए, फिर लहसुन, शिमला मिर्च, ब्रोकली के फूल और हरा प्याज़ डालें, साथ में 2 बड़े चम्मच पानी।","3 मिनट तक चलाते हुए भूनें, फिर पाक चोई, वॉटर चेस्टनट और ऑयस्टर सॉस डालें। अच्छी तरह गरम होने दें और तुरंत परोसें।"],
["आप बीफ़ की जगह दुबला पोर्क या चिकन इस्तेमाल कर सकते हैं।","शाकाहारी संस्करण के लिए, पट्टियों में कटा हुआ सख़्त टोफू इस्तेमाल करें। हर तरफ़ 3–4 मिनट तलें, फिर पैन से निकाल लें, बाकी सामग्री पकाएँ, टोफू वापस डालें, अच्छी तरह मिलाएँ और परोसें।",fv(2)]))
r.append(R(7519383,"मलाईदार चिकन और मशरूम सूप",
"पारंपरिक सूप का मेल जो कम वसा वाला है और पूरे परिवार के लिए उपयुक्त है।",
"4","301 ग्राम",
["2 छोटे चम्मच तेल","2 प्याज़, कटे हुए","2 बिना त्वचा के चिकन ब्रेस्ट (लगभग 200 ग्राम), छोटे कटे हुए","250 ग्राम मशरूम","2 फांक लहसुन, कुचला हुआ","1 चिकन स्टॉक क्यूब, 500 मिलीलीटर पानी में घोला हुआ","1 ढेर वाला छोटा चम्मच कॉर्नफ्लोर","अच्छी बड़ी चुटकी सफ़ेद मिर्च","300 मिलीलीटर स्किम्ड दूध","100 ग्राम 0% वसा वाला ग्रीक दही","2 छोटे चम्मच कटा हुआ चाइव्स","थोड़ी पिसी काली मिर्च"],
["पैन में तेल डालें और प्याज़ को 5 मिनट धीमी आँच पर पकाएँ, बीच-बीच में चलाते रहें।","चिकन डालें और 2-3 मिनट चलाएँ।","मशरूम और लहसुन डालें और 2-3 मिनट और पकाएँ।","स्टॉक डालें, अच्छी तरह मिलाएँ, उबाल आने दें, आँच धीमी करें, ढक्कन से ढकें और 15 मिनट धीमी आँच पर पकाएँ।","एक जग में कॉर्नफ्लोर और सफ़ेद मिर्च को एक साथ मिलाएँ और दूध मिलाएँ।","दूध और कॉर्नफ्लोर के मिश्रण को धीरे-धीरे चिकन और मशरूम में मिलाएँ, लगातार चलाते हुए, फिर लगभग उबाल आने तक गरम करें।","दही मिलाएँ, आँच से उतारें और मिश्रण को चिकना होने तक ब्लेंड करें। ऊपर से चाइव्स और काली मिर्च छिड़ककर परोसें।"],
["आप स्टिक ब्लेंडर या ब्लेंडर का इस्तेमाल कर सकते हैं।","ताज़ा टैरागन, अजमोदा (पार्सले) या तुलसी जैसी जड़ी-बूटियाँ डालकर देखें। 1 छोटा चम्मच पिसे जीरे से इसे मसालेदार बनाएँ।","फ्रीज़ करने के निर्देश: व्यक्तिगत सर्विंग के लिए छोटे डिब्बों में फ्रीज़ किया जा सकता है। माइक्रोवेव में या बहुत धीमी आँच पर अंदर तक गरम होने तक डीफ़्रॉस्ट करें।",fv(1)]))
r.append(R(7520378,"पास्ता इन ब्रोदो",
"सूखे, टूटे हुए पास्ता और आपकी पसंद की किसी भी सब्ज़ी के इस्तेमाल के लिए एक बढ़िया व्यंजन।",
"2","484 ग्राम",
["120 ग्राम साबुत गेहूँ के पास्ता शेप्स (सूखा वज़न)","1 बड़ा चम्मच ऑलिव ऑयल","1 प्याज़, बारीक कटा हुआ","1 पीली शिमला मिर्च, कटी हुई","1 गाजर, छोटे टुकड़ों में कटी हुई","300 मिलीलीटर वेजिटेबल स्टॉक, या 500 मिलीलीटर कम नमक वाला वेजिटेबल स्टॉक","1 ढेर वाला छोटा चम्मच सूखा ओरेगैनो","2 बड़े बेल पर पके टमाटर, कटे हुए","50 ग्राम ताज़े फ्रोज़न एडामामे बीन्स, डीफ़्रॉस्ट किए हुए","2 पत्तागोभी के पत्ते, कटे हुए","2 छोटे चम्मच पेस्टो","10 ग्राम पारमेज़ान चीज़, परोसने के लिए"],
["पास्ता को उबलते पानी के पैन में डालें, 8 मिनट पकाएँ, फिर छान लें।","इसी बीच, पैन में ऑलिव ऑयल डालें और प्याज़, पीली शिमला मिर्च और गाजर मिलाएँ। 5 मिनट बीच-बीच में चलाएँ, जब तक भूरे होने न लगें।","स्टॉक और ओरेगैनो डालें, उबाल आने दें, फिर आँच कम करें और एडामामे बीन्स और पत्तागोभी डालें। फिर से हल्का उबाल आने दें, 2 मिनट बीच-बीच में चलाएँ।","पास्ता डालें, फिर से हल्का उबाल आने दें, फिर आँच से उतार लें।","दो कटोरों में बाँटें और हर एक में पेस्टो की एक बूँद डालें। परोसने के लिए, ढेर सारी काली मिर्च और थोड़ा पारमेज़ान चीज़ छिड़कें।"],
["यह किसी भी सूखे, टूटे हुए पास्ता और लगभग किसी भी सब्ज़ी के इस्तेमाल के लिए बढ़िया है।","इस व्यंजन में नमक कम करने के लिए कम नमक वाला स्टॉक चुनें, या अपना खुद का बनाएँ।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फिर फ्रिज या माइक्रोवेव में डीफ़्रॉस्ट करें और अंदर तक गरम होने तक दोबारा गरम करें।",fv(4)]))
r.append(R(7521021,"चुकंदर और गाजर का केक",
"अनानास और अनानास का रस इस चुकंदर और गाजर के केक को अतिरिक्त ताज़गी देते हैं।",
"10","100 ग्राम",
["200 ग्राम सादा साबुत गेहूँ का आटा","2 छोटे चम्मच बेकिंग पाउडर","1 छोटा चम्मच बेकिंग सोडा","1 छोटा चम्मच पिसी दालचीनी","100 ग्राम कच्चा कद्दूकस किया चुकंदर","100 ग्राम कद्दूकस की हुई गाजर, निचोड़कर सुखाई हुई","4 अंडे","100 ग्राम बारीक चीनी (कैस्टर शुगर)","435 ग्राम का डिब्बा जूस में कुटा हुआ अनानास","1 बड़ा चम्मच आइसिंग शुगर"],
["ओवन को 150C/गैस 2 पर पहले से गरम करें। 20 सेमी की अलग होने वाली तली वाली केक टिन में तेल लगाएँ और अस्तर बिछाएँ।","आटा, बेकिंग पाउडर, बेकिंग सोडा और दालचीनी को एक बड़े कटोरे में छान लें। चुकंदर, आधी गाजर डालें, और बराबर मिलाएँ। 2 अंडों की सफ़ेदी को एक कटोरे में डालें और नरम चोटियाँ बनने तक फेंटें। बची हुई ज़र्दी और पूरे अंडे बारीक चीनी के साथ एक कटोरे में डालें और इलेक्ट्रिक व्हिस्क से 4-5 मिनट फेंटें जब तक हल्का रंग और गाढ़ा न हो जाए।","अनानास का रस एक पैन में निथार लें। अनानास को काटें और उसे अंडे की सफ़ेदी और फेंटे हुए अंडों के साथ आटे के मिश्रण में डालें और हल्के से धीरे-धीरे मिलाएँ जब तक बराबर मिल न जाए। केक टिन में चम्मच से डालें। ऊपर बची हुई गाजर बिखेरें और आइसिंग शुगर छिड़कें।","75 मिनट बेक करें, फिर फ़ॉइल से ढकें और 15 मिनट और बेक करें, या जब तक बीच में डाली गई सींक साफ़ न निकले। तार की जाली पर उलटकर निकालें और ठंडा होने दें।","अनानास के रस को 5-6 मिनट धीमी आँच पर पकाएँ जब तक चाशनी जैसा न हो जाए। गरम केक पर डालें और ठंडा होने के लिए छोड़ दें।"],[]))
r.append(R(7521301,"गोल्डन सूप",
"\"यह रेसिपी एक कटोरे में छुट्टियों जैसा एहसास देती है। मेरे बच्चों को भी यह पसंद है, और यह तैयार करना इतना आसान है कि 'नन्हे हाथ' भी सब्ज़ियों में मदद कर सकते हैं। मैं इसे 'गोल्डन सूप' कहती हूँ क्योंकि जब आप इसे ब्लेंड करते हैं, तो यह तरल सोने जैसा दिखता है।\"",
"6","290 ग्राम",
["1 लाल प्याज़","1 सफ़ेद प्याज़","1 लाल शिमला मिर्च","2 पीली/नारंगी शिमला मिर्च","2 बड़ी या 4 छोटी तोरी (कूजेट)","2 टमाटर","एक चुटकी सूखी, मिली-जुली जड़ी-बूटियाँ","1 ढेर वाला छोटा चम्मच न्यूट्रिशनल यीस्ट","स्प्रे तेल (वैकल्पिक)","1 कम नमक वाला स्टॉक क्यूब (वैकल्पिक)","500 मिलीलीटर उबलता पानी"],
["ओवन को 180°C (फैन 160°C)/350°F/गैस 4 पर पहले से गरम करें।","सारी सब्ज़ियों को टुकड़ों में काटें, सूखी मिली-जुली जड़ी-बूटियाँ और न्यूट्रिशनल यीस्ट छिड़कें, भूनने की प्रक्रिया तेज़ करने के लिए अपनी पसंद का तेल स्प्रे करें। मैं अक्सर बिना तेल के भूनती हूँ और सब्ज़ियाँ अच्छी तरह भुनती हैं और अपनी नमी बनाए रखती हैं। ओवन के बीच में रखें और 25 – 30 मिनट तक भूनें, जब तक सब्ज़ियाँ किनारों पर सुनहरी और भूरी न हो जाएँ।","स्टॉक को गुनगुने पानी में घोलें ताकि ब्लेंडर में डालने के लिए तैयार हो।","भुनी हुई सब्ज़ियाँ, पानी और स्टॉक को ब्लेंडर में डालें और चिकना होने तक ब्लेंड करें। पैन में डालें और गरम रखें। नमक-मसाला जाँचें और परोसें।"],
["यह रेसिपी बैलेंस पत्रिका की कवर स्टार शिवाली ने मधुमेह (डायबिटीज़) से राहत की अपनी यात्रा के हिस्से के रूप में बनाई है।",fv(2)]))
r.append(R(7522633,"वसंत की सब्ज़ियों के साथ चिकन रिसोटो",
"रोज़ के रात के खाने का एक व्यंजन जो पोषण से भरपूर है।",
"4","293 ग्राम",
["1 छोटा चम्मच ऑलिव ऑयल","1 छोटा प्याज़, बारीक कटा हुआ","1 फांक लहसुन, कुचला हुआ","2 बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट, टुकड़ों में कटे हुए","225 ग्राम रिसोटो राइस","1 लीटर गरम चिकन स्टॉक","1 x 100 ग्राम का पैकेट शतावरी (एस्पेरेगस) की डंडियाँ, आधी कटी हुई","150 ग्राम फ्रोज़न मटर","2 बड़े चम्मच पारमेज़ान चीज़","2 बड़े चम्मच ताज़ा कटा अजमोदा (पार्सले)","ताज़ी पिसी काली मिर्च"],
["एक बड़े नॉन-स्टिक फ्राइंग पैन में तेल गरम करें, प्याज़ और लहसुन डालें और 1 मिनट भूनें। चिकन डालें और 2–3 मिनट भूनते रहें।","चावल डालें और तेल में लपेटें। धीरे-धीरे गरम स्टॉक डालें, लगातार चलाते हुए, हर बार अगला डालने से पहले पिछला सोख लेने दें।","स्टॉक के आख़िरी हिस्से के साथ शतावरी और मटर मिलाएँ और पकाते रहें। पूरी पकाने की प्रक्रिया में लगभग 20 मिनट लगने चाहिए और चावल 'अल डेंटे' (हल्का सख़्त) होना चाहिए।","पारमेज़ान चीज़ और अजमोदा मिलाएँ, अच्छी तरह नमक-मसाला डालें और परोसें।"],
["अपने स्टॉक को दूसरे पैन में गरम रखें ताकि जब आप उसे व्यंजन में डालें तो तापमान न गिरे और चावल का पकना न रुके।","शाकाहारी विकल्प के लिए, पारमेज़ान चीज़ छोड़ दें, चिकन की जगह 200 ग्राम मशरूम डालें और वेजिटेबल स्टॉक इस्तेमाल करें।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज में डीफ़्रॉस्ट करें और अंदर तक गरम होने तक दोबारा गरम करें।",fv(1)]))
r.append(R(7523019,"इतालवी शैली के ब्रेज़ किए मेमने के स्टेक",
"जड़ी-बूटियों और टमाटर से भरपूर व्यंजन जो मेमने का पूरा स्वाद उभारता है।",
"4","301 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","4 लाल प्याज़, चार टुकड़ों में कटे हुए","4 मेमने के स्टेक (लगभग 500 ग्राम), चर्बी हटाई हुई","1 बड़ा चम्मच आटा","4 फांक लहसुन, कटा हुआ","रोज़मेरी की बड़ी टहनी, टुकड़ों में फाड़ी हुई, साथ में परोसने के लिए थोड़ी या 1 छोटा चम्मच सूखा रोज़मेरी (समतल भरा हुआ)","1 ढेर वाला छोटा चम्मच ओरेगैनो","1 मेमने का स्टॉक क्यूब, 500 मिलीलीटर पानी में घोला हुआ","1 x 400 ग्राम का डिब्बा कटे हुए टमाटर","1 बड़ा चम्मच बाल्सामिक सिरका","अच्छी बड़ी चुटकी काली मिर्च"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। पैन में मध्यम-धीमी आँच पर 1 छोटा चम्मच तेल डालें, प्याज़ डालें और बार-बार पलटते हुए 3-4 मिनट धीरे-धीरे भूरा करें। एक तरफ़ रख दें।","मेमने पर आटा लगाएँ और बचा हुआ तेल पैन में डालें। हर तरफ़ 2-3 मिनट पकाएँ।","प्याज़ को वापस पैन में डालें, लहसुन, रोज़मेरी और ओरेगैनो डालें। स्टॉक मिलाएँ और हल्का उबाल आने दें।","टमाटर, बाल्सामिक सिरका और काली मिर्च डालें।","ओवन-प्रूफ़ डिश में रखें और 45-50 मिनट पकाएँ। थोड़े ताज़े रोज़मेरी से सजाकर परोसें।"],
["यदि आप चाहें तो पूरा व्यंजन चूल्हे पर भी पका सकते हैं – बस 45-50 मिनट धीमी आँच पर पकाएँ। ध्यान रखें कि पानी पूरी तरह न सूख जाए, इसलिए ज़रूरत हो तो थोड़ा पानी डालें।","बिना त्वचा की चिकन जाँघों के साथ अच्छा लगता है।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज या माइक्रोवेव में डीफ़्रॉस्ट करें और अंदर तक गरम होने तक दोबारा गरम करें।",fv(3)]))
r.append(R(7523365,"तीखा तरबूज़, टमाटर और पाइन नट्स का सलाद",
"आपकी मेज़ के लिए एक स्वादिष्ट और आँखों को भाने वाला जोड़, यह ताज़गी भरा तरबूज़ का सलाद गर्मियों का एकदम सही व्यंजन है",
"4","252 ग्राम",
["7 चेरी टमाटर, आधे कटे हुए","1 बड़ा चम्मच बाल्सामिक सिरका","1/2 नींबू (लाइम), केवल रस","2 बड़े चम्मच कटा हुआ पुदीना","6 बड़ी तुलसी की पत्तियाँ, हाथ से मोटी फाड़ी हुई","500 ग्राम बिना बीज का तरबूज़, छिलका हटाकर 24 निवाले के आकार के टुकड़ों में कटा हुआ: खाने योग्य वज़न 380 ग्राम","1/2 पैकेट स्ट्रॉबेरी, लगभग 7, डंठल निकालकर चार टुकड़ों में कटी हुई","1/2 खीरा, छँटा हुआ","100 ग्राम एडामामे बीन्स, डीफ़्रॉस्ट किए हुए","20 ग्राम भुने हुए पाइन नट्स"],
["टमाटर, बाल्सामिक सिरका, नींबू का रस, पुदीना और तुलसी को मिलाएँ और परोसने की प्लेट पर डालें। ऊपर तरबूज़ और स्ट्रॉबेरी बिखेरें।","वेजिटेबल पीलर से खीरे की लंबी पट्टियाँ छीलें और सलाद के ऊपर सजाएँ। परोसने के लिए ऊपर एडामामे बीन्स और भुने हुए पाइन नट्स बिखेरें।"],
[fv(2)]))
r.append(R(7524534,"मशरूम पाते",
"यह कम वसा वाला आसान पाते एक आदर्श शाकाहारी स्टार्टर है।",
"4","81 ग्राम",
["1 बड़ा चम्मच ऑलिव ऑयल","50 ग्राम शैलट (छोटे प्याज़), बारीक कटे हुए","125 ग्राम शिटाके मशरूम, पतले कटे हुए","75 ग्राम चेस्टनट मशरूम, पतले कटे हुए","1 फांक लहसुन, कुचला हुआ","अच्छी बड़ी चुटकी सफ़ेद मिर्च","1 छोटा चम्मच कम नमक वाला सोया सॉस","1 बड़ा चम्मच ताज़ा अजमोदा (पार्सले), बारीक कटा हुआ","50 ग्राम आधी वसा वाला सॉफ़्ट चीज़"],
["मध्यम आँच पर पैन में तेल डालें, फिर शैलट डालें, 5 मिनट बार-बार चलाते हुए भूरा होने तक पकाएँ।","सारे मशरूम डालें और आँच थोड़ी तेज़ करें। 3-4 मिनट पकाएँ जब तक मशरूम नरम न हो जाएँ और उनसे निकला कोई भी तरल सूख न जाए।","लहसुन और काली मिर्च डालें, 1 मिनट और पकाएँ, फिर सोया सॉस और अजमोदा डालें, मिलाएँ, फिर आँच से उतारें और ठंडा होने दें।","मशरूम को चॉपिंग बोर्ड पर रखें और बारीक काटें, फिर क्रीम चीज़ के साथ एक कटोरे में डालें, मिलाएँ और फ्रिज में रखें। टोस्ट के साथ परोसें।"],
["इस पाते से 15–20 बढ़िया कैनपे भी बनते हैं। गेहूँ-मुक्त कैनपे के लिए, बेक किए हुए छोटे आलू इस्तेमाल करके देखें – पके आलू को आधा काटें, थोड़ा आलू का गूदा निकालें, फिर बीच में पाते भरें।","ग्लूटेन-मुक्त पाते के लिए, इस रेसिपी में सोया सॉस की जगह कम नमक वाला, ग्लूटेन-मुक्त तमारी इस्तेमाल करें।","फ्रीज़ करने के निर्देश: परोसने के लिए फ्रिज में डीफ़्रॉस्ट करें।",fv(0)]))
r.append(R(7525579,"एवोकाडो और काली बीन्स के साथ नाश्ते के अंडे",
"एवोकाडो और अंडों का एक सरल लेकिन स्वादिष्ट रूप, मिर्च की हल्की झलक के साथ।",
"2","322 ग्राम",
["1 बड़ा एवोकाडो","2 छोटे अंडे","1 छोटा चम्मच रेपसीड तेल","1/2 लाल मिर्च, बीज निकालकर बारीक कटी हुई","200 ग्राम पानी में डिब्बाबंद काली बीन्स","8 चेरी टमाटर, मोटे कटे हुए","1/2 छोटा चम्मच चिपोटले पेस्ट","2 हरे प्याज़, बारीक कटे हुए"],
["ओवन को 200C/गैस 6 पर पहले से गरम करें। एवोकाडो को आधा काटें, गुठली निकालें और हर आधे से 1 बड़ा चम्मच गूदा निकालें (किसी और रेसिपी के लिए रख लें)। हर एक को सीधा रखने के लिए रैमेकिन में रखें। हर एक में एक अंडा तोड़कर डालें और 12–15 मिनट बेक करें, जब तक ज़र्दी जम न जाए।","एक छोटे नॉन-स्टिक फ्राइंग पैन में तेल गरम करें। मिर्च डालें और नरम होने तक पकाएँ। बीन्स और उनके डिब्बे का रस, टमाटर और चिपोटले पेस्ट डालें। 5 मिनट धीमी आँच पर पकाएँ, जब तक गरम न हो जाएँ और टमाटर नरम होने न लगें।","व्यंजन को प्लेट पर सजाएँ, ऊपर हरा प्याज़ बिखेरें।"],
["यदि आपके अंडे थोड़े बड़े हैं, तो ज़र्दी अलग करें, हर एवोकाडो में एक ज़र्दी डालें, सफ़ेदी को काँटे से तोड़ने के लिए फेंटें, और हर एवोकाडो के गड्ढे को भरने के लिए इस्तेमाल करें।","शिशुओं, बच्चों, गर्भवती महिलाओं, बुज़ुर्गों और अस्वस्थ लोगों जैसे 'जोखिम वाले' समूहों को नरम/हल्के पके और कच्चे अंडों से बचना चाहिए, जब तक कि वे यह सुनिश्चित न कर सकें कि वे लायन कोड क्वालिटी एश्योरेंस स्कीम के तहत उत्पादित हैं।",fv(2)]))
r.append(R(7532555,"फल और मेवों के बार",
"ये चबाने वाले बार एक आदर्श स्नैक हैं।",
"16","58 ग्राम",
["450 ग्राम खाने वाले सेब, छिले, बीज निकालकर उबाले हुए (425 ग्राम)","5 बड़े चम्मच संतरे का जूस","225 ग्राम मिले-जुले सूखे फल (जैसे खुबानी, खजूर, क्रैनबेरी), मोटे कटे हुए","100 ग्राम मिले-जुले मेवे (जैसे बादाम, हेज़लनट), कटे हुए","75 ग्राम साबुत गेहूँ का सेल्फ-राइज़िंग आटा","25 ग्राम सूखा नारियल (डेसिकेटेड)","1 बड़ा चम्मच रेपसीड तेल"],
["ओवन को 180ºC/गैस 4 पर पहले से गरम करें और 20 सेमी चौकोर बेकिंग टिन को हल्का चिकना करके अस्तर बिछाएँ।","सारी सामग्री को एक कटोरे में डालें और एक साथ मिलाएँ।","बेकिंग टिन में चम्मच से डालें।","समतल करें और हल्का दबाएँ, फिर 35–40 मिनट बेक करें, जब तक सुनहरा और ठोस न हो जाए।","16 टुकड़ों के निशान लगाएँ। टिन में ही ठंडा होने दें। थोड़ा ठंडा होने पर परोसें।"],
["सेब उबालने के लिए: उन्हें छीलें, बीज निकालें और काटें, फिर 2 बड़े चम्मच पानी के साथ पैन में डालें। ढककर धीमी आँच पर 10-15 मिनट बीच-बीच में चलाते हुए पकाएँ।","उबाले हुए सेब अच्छी तरह फ्रीज़ होते हैं, इसलिए आप एक बैच बनाकर ज़रूरत पड़ने तक फ्रीज़ कर सकते हैं।","फ्रीज़ करने के निर्देश: परोसने के लिए 2 घंटे डीफ़्रॉस्ट करें, या माइक्रोवेव में या मध्यम गरम ओवन में डीफ़्रॉस्ट करें।",fv(0)]))
r.append(R(7533762,"तंदूरी चिकन और सब्ज़ियाँ",
"सब कुछ एक ही समय में ओवन में जाता है, जो इसे वाकई एक सरल और स्वादिष्ट व्यंजन बनाता है।",
"2","594 ग्राम",
["300 ग्राम बिना त्वचा का चिकन ब्रेस्ट","1 बड़ा चम्मच कम वसा वाला सादा दही","1 छोटा चम्मच पपरिका","1 छोटा चम्मच पिसा जीरा","1 छोटा चम्मच हल्दी","4 टमाटर, आधे कटे हुए","1 छोटा चम्मच गरम मसाला","1 छोटा चम्मच रेपसीड तेल","2 बड़े लाल प्याज़, चार टुकड़ों में कटे हुए","1 लाल शिमला मिर्च, 8 टुकड़ों में कटी हुई"],
["ओवन को 200°C/गैस 6 पर पहले से गरम करें। चिकन को टुकड़ों में काटें और दही, पपरिका, जीरा और हल्दी के साथ एक कटोरे में डालें, फिर अच्छी तरह मिलाएँ ताकि चिकन पर परत चढ़ जाए।","टमाटरों पर गरम मसाला छिड़कें।","बेकिंग ट्रे पर हल्का तेल लगाएँ और उस पर प्याज़ और शिमला मिर्च को बराबर सजाएँ, फिर चिकन के टुकड़ों को प्याज़ और शिमला मिर्च पर रखें, और टमाटरों को ऊपर सजाएँ।","15 मिनट भूनें, या जब तक चिकन अंदर तक अच्छी तरह पक न जाए, और बासमती चावल या सलाद के साथ परोसें।"],
["यदि आपके पास सारे मसाले नहीं हैं तो करी पेस्ट इस्तेमाल करें, या अतिरिक्त स्वाद के लिए कद्दूकस किया ताज़ा अदरक और कुचला लहसुन डालें।","आप चिकन, मसाले और दही को फ़ूड बैग में मिलाकर पकाना शुरू करने से कुछ घंटे पहले फ्रिज में रख सकते हैं, जिससे स्वाद रच-बस जाते हैं।","मसालेदार व्यंजनों में आमतौर पर अतिरिक्त नमक की ज़रूरत नहीं होती, जिसका मतलब है कि वे आपके दिल के लिए बेहतर हैं।","बिना त्वचा का चिकन प्रोटीन से भरपूर होता है और त्वचा वाले चिकन की तुलना में उसमें लगभग आधी वसा और संतृप्त वसा होती है।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज या माइक्रोवेव में डीफ़्रॉस्ट करें और अंदर तक अच्छी तरह गरम होने तक दोबारा गरम करें।",fv(5)]))
